// route-extraction script (slice 140 build); hand-edit entries to refine
// the Summary field for richer Redoc rendering. The order is sorted by
// (Method, Path) — keep new entries in sort order so diffs stay clean.
package openapi

// RouteSpec describes one HTTP route in the OpenAPI surface.
type RouteSpec struct {
	Method   string // HTTP method: GET, POST, PATCH, PUT, DELETE
	Path     string // chi-shaped path, e.g. /v1/controls/{id}
	Tag      string // Single tag for Redoc grouping (e.g. "risks", "controls")
	Tier     string // Auth tier: "none" | "bearer" | "adminBearer"
	Internal bool   // True for operator-only endpoints filtered from public Redoc
	Summary  string // One-line summary; rendered as the Redoc operation header
}

